	DesolaceCentaurs = function(t,tooltipInfo)local reputation=t.reputation if reputation>0 and reputation<9000 then	_.Modules.FactionData.AddReputationTooltipInfo(tooltipInfo,reputation,"Kill Centaurs to Honored.",20,9000)end	end,
	ForAlteracValley = function(t,tooltipInfo)local reputation=t.reputation if reputation>=0 and reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo addRepInfo(tooltipInfo,reputation,"Concerted Efforts",150,42000)addRepInfo(tooltipInfo,reputation,"Kill the General",389,42000)addRepInfo(tooltipInfo,reputation,"Kill a Captain",125,42000)addRepInfo(tooltipInfo,reputation,"Kill a Commander",12,42000)addRepInfo(tooltipInfo,reputation,"Kill an Air Master",5,42000)if reputation<21000 then	addRepInfo(tooltipInfo,reputation,"Kill a Guard (To Revered)",5,21000)end	end	end,
	ForArathiBasin = function(t,tooltipInfo)local reputation=t.reputation if reputation>=0 and reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo addRepInfo(tooltipInfo,reputation,"Concerted Efforts",100,42000)_.Modules.FactionData.AddReputationTooltipInfoWithMultiplier(tooltipInfo,reputation,"Total Resources",10,42000,200)addRepInfo(tooltipInfo,reputation,"Resource Ticks",10,42000)tooltipInfo[#tooltipInfo+1]={left=" Every 200 or 150 Resources during AB Weekend.",r=1,g=1,b=1}end	end,
	ForEverlook = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo addRepInfo(tooltipInfo,reputation,"Kill Pirates in Ratchet*",2.5,42000)addRepInfo(tooltipInfo,reputation,"Kill Pirates in Tanaris",2.5,42000)tooltipInfo[#tooltipInfo+1]={left=" * PROTIP: Ratchet is faster.",r=1,g=0.5,b=0.5}end	end,
	ForLockpicking = function(t,tooltipInfo)local skills=_.CurrentCharacter.ActiveSkills[t.spellID] if skills and skills[1]<300 then	local data=t.lpdata if not data then	data={}local requireSkill=t.requireSkill _:BuildFlatSearchFilteredResponse(_:GetDatabaseRoot().g,function(group)return group.requireSkill==requireSkill and group.learnedAt and not group.nmr end,data)table.sort(data,function(a,b)return a.learnedAt>b.learnedAt end)t.lpdata=data end	tooltipInfo[#tooltipInfo+1]={left="Recommended Locations:",right="Minimum"}local lastLearnedAt for i,o in ipairs(data)do	if o.learnedAt<=skills[2] then	if o.learnedAt<skills[1] then	if lastLearnedAt and o.learnedAt<lastLearnedAt then	break end	lastLearnedAt=o.learnedAt end	local text="  "..o.text mapID=_.GetBestMapForGroup(o,_.CurrentMapID)if mapID then text=text.." (".._.GetMapName(mapID)..")" end	tooltipInfo[#tooltipInfo+1]={left=text,right=tostring(o.learnedAt),r=1,g=1,b=1}end	end	end	end,
	ForRatchet = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo if reputation<20999 then	addRepInfo(tooltipInfo,reputation,"Kill Pirates in Ratchet (To 11999 Honored)",5,20999)end	addRepInfo(tooltipInfo,reputation,"Kill Pirates in Tanaris",2.5,42000)end	end,
	ForTimbermawHold = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo if reputation>=0 then	if not t.deadwood then	local f=_.SearchForField("questID",8470)if f and #f>0 then t.deadwood=f[1] end	end	if not t.winterfall then	local f=_.SearchForField("questID",8471)if f and #f>0 then t.winterfall=f[1] end	end	if not t.deadwood.saved then	_.Modules.FactionData.AddQuestTooltip(tooltipInfo,"Complete %s",t.deadwood)end	if not t.winterfall.saved then	_.Modules.FactionData.AddQuestTooltip(tooltipInfo,"Complete %s",t.winterfall)end	end	if reputation<8999 then	addRepInfo(tooltipInfo,reputation,"Kill Deadwood Furbolgs (Stops at Honored)",5,8999,-3000)end	if reputation<20999 then	addRepInfo(tooltipInfo,reputation,"Kill Winterfall Furbolgs (Stops at Revered)",5,20999,-3000)end	local repPerTurnIn=50 addRepInfo(tooltipInfo,reputation,"Turn in Deadwood Feathers (x5) in Felwood",repPerTurnIn,42000)local repPer,remainingTurnIns=addRepInfo(tooltipInfo,reputation,"Turn in Winterfall Beads (x5) in Winterspring",repPerTurnIn,42000)local remaining=((remainingTurnIns * 5)- _.WOWAPI.GetItemCount(21383,true)- _.WOWAPI.GetItemCount(21377,true))if remaining>0 then	tooltipInfo[#tooltipInfo+1]={left="You need "..remaining.." more feathers/beads for Exalted.",r=1,g=1,b=0}end	if reputation<8999 then	tooltipInfo[#tooltipInfo+1]={left=" * PROTIP: Do NOT turn in the totems or feathers until after Honored!",r=1,g=0.5,b=0.5}end	end	end,
	ForWarsongGulch = function(t,tooltipInfo)local reputation=t.reputation if reputation>=0 and reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo addRepInfo(tooltipInfo,reputation,"Concerted Efforts",100,42000)local repPerFlagCapture=35 addRepInfo(tooltipInfo,reputation,"Flags Captured",repPerFlagCapture,42000)tooltipInfo[#tooltipInfo+1]={left=" Each capture is worth "..repPerFlagCapture.." rep, +10 on WSG Weekend.",r=1,g=1,b=1}end	end,
	Ravenholdt = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	tooltipInfo[#tooltipInfo+1]={left=" * PROTIP: Bring a stack of Repair Bots with you.",r=0.5,g=1,b=0.5}_.Modules.FactionData.AddReputationTooltipInfoWithMultiplier(tooltipInfo,reputation,"Turn in Heavy Junkboxes.",50,42000,5)end	end,
	RuneclothTurnIns = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	_.Modules.FactionData.AddReputationTooltipInfo(tooltipInfo,reputation,"Runecloth Turn Ins",50,42000)end	end,
	ThoriumBrotherhood = function(t,tooltipInfo)local reputation=t.reputation if reputation<42000 then	local addRepInfo=_.Modules.FactionData.AddReputationTooltipInfo addRepInfo(tooltipInfo,reputation,"Turn In Blood & Cores (1x each)",200,42000)addRepInfo(tooltipInfo,reputation,"Turn In Core Leather (2x each)",150,42000)addRepInfo(tooltipInfo,reputation,"Turn In Dark Iron Ore (10x each)",50,42000)end	end
}
_.OnUpdateDB=
{
	ForLockpicking = function(t)if _.Settings.Collectibles.Recipes then	t.collectible=true local id=t.spellID local skills=_.CurrentCharacter.ActiveSkills[id] if skills and skills[1]>=300 then	t.collected=1 return end	if _.Settings.AccountWide.Recipes then	for guid,ch in pairs(ATTCharacterData)do	skills=ch.ActiveSkills and ch.ActiveSkills[id] if skills and skills[1]>=300 then	t.collected=2 return end	end	end	t.collected=false else	t.collectible=false end	end
}
